static inline uint32_t flb_utf8_decode(uint32_t *state, uint32_t *codep, uint32_t byte)
{
    uint32_t type = utf8d[byte];
    *codep = (*state != FLB_UTF8_ACCEPT) ?
        (byte & 0x3fu) | (*codep << 6) :
        (0xff >> type) & (byte);
    *state = utf8d[256 + *state*16 + type];
    return *state;
}

static inline void encoded_to_buf(char *out, const char *in, int len)
{
    int i;
    char *p = out;
    for (i = 0; i < len; i++) {
        *p++ = in[i];
    }
}

int flb_utils_write_str(char *buf, int *off, size_t size,
                        const char *str, size_t str_len)
{
    int i;
    int b;
    int ret;
    int written = 0;
    int required;
    int len;
    int hex_bytes;
    uint32_t codepoint;
    uint32_t state = 0;
    char tmp[16];
    size_t available;
    uint32_t c;
    char *p;
    uint8_t *s;

    available = (size - *off);
    required = str_len;
    if (available <= required) {
        return FLB_FALSE;
    }

    p = buf + *off;
    for (i = 0; i < str_len; i++) {
        if ((available - written) < 2) {
            return FLB_FALSE;
        }

        c = (uint32_t) str[i];
        if (c == '\"') {
            *p++ = '\\';
            *p++ = '\"';
        }
        else if (c == '\\') {
            *p++ = '\\';
            *p++ = '\\';
        }
        else if (c == '\n') {
            *p++ = '\\';
            *p++ = 'n';
        }
        else if (c == '\r') {
            *p++ = '\\';
            *p++ = 'r';
        }
        else if (c == '\t') {
            *p++ = '\\';
            *p++ = 't';
        }
        else if (c == '\b') {
            *p++ = '\\';
            *p++ = 'b';
        }
        else if (c == '\f') {
            *p++ = '\\';
            *p++ = 'f';
        }
        else if (c < 32 || c == 0x7f) {
            if ((available - written) < 6) {
                return FLB_FALSE;
            }
            len = snprintf(tmp, sizeof(tmp) - 1, "\\u%.4hhx", (unsigned char) c);
            encoded_to_buf(p, tmp, len);
            p += len;
        }
        else if (c >= 0x80 && c <= 0xFFFF) {
            hex_bytes = flb_utf8_len(str + i);
            if (available - written < 6) {
                return FLB_FALSE;
            }
            if (i + hex_bytes > str_len) {
                break;
            }
            state = FLB_UTF8_ACCEPT;
            codepoint = 0;
            for (b = 0; b < hex_bytes; b++) {
                s = (unsigned char *) str + i + b;
                ret = flb_utf8_decode(&state, &codepoint, *s);
                if (ret == 0) {
                    break;
                }
            }
            if (state != FLB_UTF8_ACCEPT) {
                break;
            }
            else {
                len = snprintf(tmp, sizeof(tmp) - 1, "\\u%.4x", codepoint);
                encoded_to_buf(p, tmp, len);
                p += len;
            }
            i += (hex_bytes - 1);
        }
        else if (c > 0xFFFF) {
            hex_bytes = flb_utf8_len(str + i);
            if (available - written < 6) {
                return FLB_FALSE;
            }
            if (i + hex_bytes > str_len) {
                break;
            }
            state = FLB_UTF8_ACCEPT;
            codepoint = 0;
            for (b = 0; b < hex_bytes; b++) {
                s = (unsigned char *) str + i + b;
                ret = flb_utf8_decode(&state, &codepoint, *s);
                if (ret == 0) {
                    break;
                }
            }
            if (state != FLB_UTF8_ACCEPT) {
                break;
            }
            else {
                len = snprintf(tmp, sizeof(tmp) - 1, "\\u%04x", codepoint);
                encoded_to_buf(p, tmp, len);
                p += len;
            }
            i += (hex_bytes - 1);
        }
        else {
            *p++ = c;
        }
        written = (p - (buf + *off));
    }

    *off += written;
    return FLB_TRUE;
}

int main() {
    /* Test: a string with a 4-byte UTF-8 sequence encoding a codepoint > 0xFFFF,
       where the buffer has exactly 6-7 bytes available. */
    /* 0xF0 0x9F 0x92 0xA9 = U+1F4A9 (pile of poo), 4-byte UTF-8 */
    char str[] = {(char)0xF0, (char)0x9F, (char)0x92, (char)0xA9, 0};
    char buf[8];
    int off = 0;
    /* available = 8, required = 4, so available > required. 
       In the c>0xFFFF branch, available-written=8 >= 6, proceed.
       codepoint = 0x1F4A9 > 0xFFFF, so snprintf produces "\\u1f4a9" = 7 chars.
       len = 7. encoded_to_buf writes 7 bytes into buf[8]. No overflow here (8 bytes avail).
       But if buf is smaller... */
    int ret = flb_utils_write_str(buf, &off, sizeof(buf), str, 4);
    printf("ret=%d off=%d buf=%.*s\n", ret, off, off, buf);
    return 0;
}
